import json
from pathlib import Path

from common import DATA, RESULTS, read_jsonl

HERE = Path(__file__).resolve().parent


def load(name: str) -> dict | None:
    p = RESULTS / name
    return json.loads(p.read_text()) if p.exists() else None


def pct(x: float) -> str:
    return f"{100 * x:.1f}%"


def main() -> None:
    lines = [
        "# Fine-tuning results",
        "",
        "Generated by `experiments/finetune/run_all.sh`. Test questions come only from documents never used in training.",
        "",
    ]
    qa = DATA / "qa.jsonl"
    if qa.exists():
        rows = read_jsonl(qa)
        lines += [
            f"Synthetic questions: {len(rows)} ({sum(r['split'] == 'train' for r in rows)} train / "
            f"{sum(r['split'] == 'test' for r in rows)} test), from "
            f"{len({r['document_id'] for r in rows})} documents.",
            "",
        ]

    ev = load("reranker_eval.json")
    tr = load("reranker_train.json")
    if ev:
        lines += [
            "## 1. Reranker: LoRA on bge-reranker-v2-m3",
            "",
            f"{ev['n_test']} test questions; gold passage in the hybrid top-30 for {pct(ev['gold_in_pool'])}.",
            "",
            "| ordering | Recall@1 | Recall@5 | MRR@10 | nDCG@10 |",
            "|---|---|---|---|---|",
        ]
        for k, m in ev["overall"].items():
            lines.append(
                f"| {k} | {m['recall@1']:.3f} | {m['recall@5']:.3f} | {m['mrr@10']:.3f} | {m['ndcg@10']:.3f} |"
            )
        lo, hi = ev["mrr_gain_lora_vs_base_95ci"]
        b, l_ = ev["overall"]["base"], ev["overall"]["lora"]
        lines += [
            "",
            f"MRR@10 gain LoRA vs base: {l_['mrr@10'] - b['mrr@10']:+.3f} (95% CI {lo:+.3f} … {hi:+.3f}).",
            f"Latency unchanged (same architecture): {ev['ms_per_query_30_candidates']['lora']:.0f} ms per query "
            "for 30 candidates.",
            "",
            "By dataset (MRR@10):",
            "",
            "| dataset | n | hybrid | base | lora |",
            "|---|---|---|---|---|",
        ]
        for s, m in ev["by_source"].items():
            lines.append(f"| {s} | {m['n']} | {m['hybrid']:.3f} | {m['base']:.3f} | {m['lora']:.3f} |")
        if tr:
            lines += [
                "",
                f"Training: {tr['train_groups']} groups (1 gold + 7 hard negatives), {tr['epochs']} epochs, "
                f"{tr['minutes']} min. Dev MRR by epoch: "
                + ", ".join(f"{h['dev_mrr']:.3f}" for h in tr["history"]),
            ]
        lines.append("")

    e2e = load("e2e_holdout_lora_reranker.json")
    if e2e:
        lines += [
            f"End-to-end held-out set with the new reranker: {e2e.get('correct')}/{e2e.get('total')} "
            "(was 32/32 with the base reranker).",
            "",
        ]

    q = load("qlora_eval.json")
    qt = load("qlora_train.json")
    if q:
        names = list(q["models"])
        lines += [
            "## 2. QLoRA: Qwen3-8B, grounded answers with citations",
            "",
            f"{q['n_test']} test items, {q['n_unanswerable']} of them unanswerable (gold passage removed).",
            "",
            "| metric | " + " | ".join(names) + " |",
            "|---" * (len(names) + 1) + "|",
        ]
        for metric in q["models"][names[0]]:
            vals = [q["models"][n][metric] for n in names]
            fmt = (lambda v: f"{v:.0f}") if metric == "mean_answer_chars" else pct
            lines.append(f"| {metric} | " + " | ".join(fmt(v) for v in vals) + " |")
        if qt:
            lines += [
                "",
                f"Training: {qt['train_examples']} guard-checked teacher answers, 4-bit NF4 base, LoRA r=16 "
                f"on all projections, {qt['epochs']} epochs, {qt['minutes']} min.",
            ]
        lines.append("")

    if ev or q:
        lines += ["## Resume lines (fill in only what the tables above support)", ""]
        if ev:
            b, l_ = ev["overall"]["base"], ev["overall"]["lora"]
            lines.append(
                f"- Fine-tuned the bge-reranker cross-encoder with LoRA on {tr['train_groups'] if tr else '?'} "
                f"synthetic queries with mined hard negatives: MRR@10 {b['mrr@10']:.2f} → {l_['mrr@10']:.2f}, "
                f"Recall@1 {b['recall@1']:.2f} → {l_['recall@1']:.2f} on held-out documents."
            )
        if q:
            bm, lm = q["models"]["qwen3_8b_base"], q["models"]["qwen3_8b_qlora"]
            tm = q["models"]["teacher_qwen3.8_27b"]
            lines.append(
                f"- QLoRA-fine-tuned Qwen3-8B on guard-filtered answers distilled from Qwen3.8-27B: answers passing "
                f"grounding checks {pct(bm['guard_pass_rate'])} → {pct(lm['guard_pass_rate'])} "
                f"(27B teacher: {pct(tm['guard_pass_rate'])}); correct refusals {pct(bm['refusal_recall'])} → "
                f"{pct(lm['refusal_recall'])}; untraceable numbers {pct(bm['untraceable_rate'])} → "
                f"{pct(lm['untraceable_rate'])}."
            )
    (HERE / "RESULTS.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
